seq = ""
with open("region.fasta") as f:
    for line in f:
        line=line.strip()
        if line.startswith(">"): continue
        seq += line
seq = seq.upper()
N=len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

found=None
for k in range(40,3,-1):
    seen={}
    hit=None
    for i in range(N-k+1):
        sub=seq[i:i+k]
        if sub in seen:
            hit=(seen[sub], i, k); break
        seen[sub]=i
    if hit:
        found=hit;break
print("Longest duplicated exact substring (fwd):", found)

# inverted repeat: substring present as revcomp elsewhere
found=None
for k in range(40,3,-1):
    seen={}
    hit=None
    for i in range(N-k+1):
        # store revcomp of each substring as key
        sub=seq[i:i+k]
        seen[rc(sub)]=(i,'rc')
    for i in range(N-k+1):
        sub=seq[i:i+k]
        p=seen.get(sub)
        if p and p[0]!=i:
            hit=(p[0], i, k); break
    if hit:
        found=hit;break
print("Longest inverted repeat (k):", found)
